css:
@import url("https://fonts.googleapis.com/css2?family=Encode+Sans+Semi+Condensed:wght@600;800&family=Encode+Sans:wght@400;500;600&display=swap");
:root{--fg:#1E5631;--fg2:#153F24;--mt:#E8F3EC;--yl:#F2C14E;--ink:#18231C;--gr:#56625A;--ln:#D5E3DA;--h:"Encode Sans Semi Condensed",system-ui,sans-serif;--b:"Encode Sans",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}[hidden]{display:none!important}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:17px;line-height:1.65;color:var(--ink);background:#fff}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--h);font-weight:800;margin:0;line-height:1.05}
.wrap{max-width:1180px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--yl);padding:8px;z-index:99}
:focus-visible{outline:3px solid var(--yl);outline-offset:2px}
.nav{display:flex;justify-content:space-between;align-items:center;height:78px;position:relative}.logo{font-family:var(--h);font-weight:800;font-size:26px;text-decoration:none;color:var(--fg);display:flex;gap:8px;align-items:center}
.menu{display:flex;gap:24px;list-style:none;margin:0;padding:0;align-items:center;font-weight:500}.menu a{text-decoration:none}.menu .cta{background:var(--fg);color:#fff;padding:9px 18px;border-radius:8px}
.burger{display:none;background:none;border:2px solid var(--fg);color:var(--fg);width:44px;height:40px;border-radius:8px;font-size:20px;cursor:pointer}
.hero{background:var(--mt);padding:50px 0 70px}.hg{display:grid;grid-template-columns:1.05fr .95fr;gap:40px;align-items:center}.hg>*{min-width:0}
.hero h1{font-size:clamp(44px,5.8vw,78px);color:var(--fg2)}.hero p{font-size:20px;color:var(--gr);margin:18px 0 26px;max-width:28em}
.btn{display:inline-block;background:var(--fg);color:#fff;text-decoration:none;font:600 16px var(--b);padding:14px 24px;border-radius:8px;border:0;cursor:pointer}.btn.y{background:var(--yl);color:var(--ink)}
.row{display:flex;gap:12px;flex-wrap:wrap}
.next{background:#fff;border-radius:18px;padding:22px;box-shadow:0 20px 40px rgba(30,86,49,.12)}.next small{color:var(--gr);font-weight:500}.next b{display:block;font-family:var(--h);font-size:30px;margin:4px 0}.next .d{font-family:var(--h);font-size:64px;color:var(--fg);line-height:1}
.next img{border-radius:12px;margin-top:14px;aspect-ratio:16/9;object-fit:cover;width:100%}
section{padding:80px 0}.sh{max-width:640px;margin-bottom:28px}.sh h2{font-size:clamp(34px,4.6vw,56px)}.sh p{color:var(--gr);margin:10px 0 0}
.sv{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.sv div{border:2px solid var(--ln);border-radius:16px;padding:20px}.sv h3{font-size:22px}.sv p{margin:6px 0 0;color:var(--gr);font-size:15px}
.plans{background:var(--mt)}.tv{background:#fff;border-radius:16px;padding:20px;margin-bottom:22px}.tv label{font-weight:600}.tv output{float:right;font-family:var(--h);font-weight:800;font-size:22px;color:var(--fg)}.tv input{width:100%;accent-color:var(--fg);margin-top:8px}
.pg{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.pc{background:#fff;border-radius:18px;padding:24px;display:flex;flex-direction:column}.pc.hot{background:var(--fg);color:#fff}
.pc h3{font-size:26px}.pc .pr{font-family:var(--h);font-weight:800;font-size:50px;line-height:1;margin:12px 0 2px}.pc .pr small{font:500 15px var(--b)}.pc .u{font-size:14px;color:var(--gr);margin-bottom:14px}.pc.hot .u{color:#BFD9C8}
.pc ul{padding-left:18px;margin:0 0 18px;flex:1}.pc li{margin:4px 0}.pc.hot .btn{background:var(--yl);color:var(--ink)}
.dl{overflow-x:auto}.dl table{width:100%;border-collapse:collapse;min-width:560px}.dl th,.dl td{text-align:left;padding:14px 12px;border-bottom:1px solid var(--ln)}.dl th{font-size:14px;color:var(--gr);font-weight:500}.dl td b{font-family:var(--h);font-size:20px}
.dl tr.soon td{background:#FFF6DC}.dl .left{font-weight:600}.dl .past{color:#9AA69E;text-decoration:line-through}
.who{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:16px}.who button{font:600 15px var(--b);background:var(--mt);border:0;border-radius:30px;padding:8px 14px;cursor:pointer;color:var(--ink)}.who button[aria-pressed=true]{background:var(--fg);color:#fff}
.con{background:var(--fg2);color:#fff}.cg{display:grid;grid-template-columns:.9fr 1.1fr;gap:50px}.con .sh p{color:#BFD9C8}
.con form{background:#fff;color:var(--ink);border-radius:18px;padding:28px}.fr{display:grid;grid-template-columns:1fr 1fr;gap:14px}.fr>div{min-width:0}
.con label{display:block;font-weight:600;font-size:15px;margin-bottom:6px}.con input,.con select,.con textarea{width:100%;font:16px var(--b);padding:11px;border:2px solid var(--ln);border-radius:10px;margin-bottom:14px;color:var(--ink);background:#fff}
.msg{visibility:hidden;margin:10px 0 0;color:var(--fg);font-weight:600}.msg.on{visibility:visible}
footer{padding:26px 0;font-size:15px;color:var(--gr)}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:980px){.hg,.cg{grid-template-columns:1fr}.sv{grid-template-columns:1fr 1fr}.pg{grid-template-columns:1fr}}
@media (max-width:760px){.burger{display:block}.menu{display:none;position:absolute;top:78px;left:0;right:0;background:#fff;flex-direction:column;align-items:flex-start;padding:18px 22px;z-index:30;box-shadow:0 10px 20px rgba(0,0,0,.06)}.menu.open{display:flex}.sv,.fr{grid-template-columns:1fr}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}

javascript:
(()=>{const $=id=>document.getElementById(id);let pick='Growing';
const P=[["Starter","Sole traders",25,["Self assessment return","Online bookkeeping software","Email support"]],["Growing","Small limited companies",79,["Year end accounts","Company tax return","Quarterly VAT returns","Phone support"]],["Complete","Busy businesses",149,["Everything in Growing","Monthly bookkeeping done for you","Payroll for up to 10","Quarterly planning call"]]];
function plans(){const t=+$('to').value;$('too').textContent='£'+t.toLocaleString('en-GB');const m=1+Math.max(0,t-50000)/250000;
$('pg').innerHTML=P.map(p=>{const pr=Math.round(p[2]*m);return`<div class="pc${p[0]==='Growing'?' hot':''}"><h3>${p[0]}</h3><div class="pr">£${pr}<small> a month</small></div><div class="u">For ${p[1].toLowerCase()}. Plus VAT.</div><ul>${p[3].map(x=>`<li>${x}</li>`).join('')}</ul><a class="btn" href="#contact" data-p="${p[0]}">Choose ${p[0]}</a></div>`}).join('');$('cp').value=`${pick}, turnover £${t.toLocaleString('en-GB')}`}
$('to').addEventListener('input',plans);$('pg').addEventListener('click',e=>{const a=e.target.closest('[data-p]');if(a){pick=a.dataset.p;$('cp').value=`${pick}, turnover £${(+$('to').value).toLocaleString('en-GB')}`}});plans();
const D=[["2026-10-05","Register for self assessment (new sole traders)","Sole trader"],["2026-10-19","PAYE payment for the tax month (by post)","Employer"],["2026-10-31","Paper self assessment return","Sole trader"],["2026-11-07","VAT return and payment (Jul to Sep quarter)","Limited company"],["2026-12-30","File online to have tax collected through PAYE","Sole trader"],["2027-01-01","Corporation tax payment (year end 31 March)","Limited company"],["2027-01-31","Online self assessment return and payment","Sole trader"],["2027-03-31","Company accounts filing (year end 30 June)","Limited company"],["2027-04-19","Final payroll submission for the tax year","Employer"]];
const today=new Date();today.setHours(0,0,0,0);let w='all';
function tb(){const r=D.filter(d=>w==='all'||d[2]===w);$('tb').innerHTML=r.map(d=>{const dd=Math.ceil((new Date(d[0])-today)/864e5);return`<tr class="${dd>=0&&dd<=30?'soon':''}"><td><b>${new Date(d[0]).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})}</b></td><td>${d[1]}</td><td>${d[2]}</td><td class="left ${dd<0?'past':''}">${dd<0?'Passed':dd===0?'Today':dd+' days'}</td></tr>`}).join('');
const nx=D.map(d=>[d,Math.ceil((new Date(d[0])-today)/864e5)]).filter(x=>x[1]>=0).sort((a,b)=>a[1]-b[1])[0];if(nx){$('nn').textContent=nx[0][1];$('nd').textContent=nx[1]}}
$('who').onclick=e=>{const b=e.target.closest('button');if(!b)return;$('who').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));w=b.dataset.w;tb()};tb();
$('cf').onsubmit=e=>{e.preventDefault();$('msg').textContent=`Thanks ${$('cn').value}. We'll email your fixed quote within one working day.`;$('msg').classList.add('on')};
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
